const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    const tokens = input.trim().split(/\s+/);
    if (tokens.length === 0 || tokens[0] === '') return;

    const N = tokens[0];
    const M = parseInt(tokens[1], 10);

    const map = {
        'a': '2', 'b': '2', 'c': '2',
        'd': '3', 'e': '3', 'f': '3',
        'g': '4', 'h': '4', 'i': '4',
        'j': '5', 'k': '5', 'l': '5',
        'm': '6', 'n': '6', 'o': '6',
        'p': '7', 'q': '7', 'r': '7', 's': '7',
        't': '8', 'u': '8', 'v': '8',
        'w': '9', 'x': '9', 'y': '9', 'z': '9'
    };

    let count = 0;
    const lenN = N.length;

    for (let i = 0; i < M; i++) {
        const word = tokens[2 + i];
        if (word.length !== lenN) {
            continue;
        }

        let match = true;
        for (let j = 0; j < lenN; j++) {
            if (map[word[j]] !== N[j]) {
                match = false;
                break;
            }
        }

        if (match) {
            count++;
        }
    }

    console.log(count);
}

solve();
